<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Workspace · {{ $school->name }}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><style>
:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc;--surface:#fff;--orange:#f97316}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--canvas);font:15px "DM Sans",sans-serif}.top{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 34px;background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;font-weight:800}.mark{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;color:#fff;background:var(--blue)}.user{color:var(--muted);font-size:13px}.layout{display:grid;grid-template-columns:230px 1fr;min-height:calc(100vh - 72px)}aside{padding:28px 18px;background:#fff;border-right:1px solid var(--line)}.nav{display:block;padding:11px 13px;margin:4px 0;border-radius:9px;color:var(--muted);text-decoration:none;font-weight:600}.nav.active,.nav:hover{color:var(--blue);background:#eef4ff}.main{max-width:1180px;width:100%;padding:44px 42px}.eyebrow{color:var(--blue);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}.heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:32px}.heading h1{margin:8px 0 0;font:800 36px/1.1 Manrope,sans-serif;letter-spacing:-.055em}.heading p{margin:8px 0 0;color:var(--muted)}.button{display:inline-flex;align-items:center;min-height:42px;padding:0 16px;border-radius:10px;background:var(--blue);color:#fff;text-decoration:none;font-weight:700}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stat,.panel{padding:22px;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:0 10px 28px #1e315308}.stat span{color:var(--muted);font-size:12px}.stat strong{display:block;margin-top:9px;font:800 30px Manrope,sans-serif;letter-spacing:-.06em}.grid{display:grid;grid-template-columns:1.15fr .85fr;gap:18px;margin-top:18px}.panel h2{margin:0;font:800 20px Manrope,sans-serif;letter-spacing:-.04em}.panel p{color:var(--muted);line-height:1.6}.profile{display:flex;align-items:center;gap:14px;margin-top:20px}.avatar{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;color:var(--blue);background:#eaf1ff;font-weight:800}.profile strong{display:block}.profile span{color:var(--muted);font-size:12px}@media(max-width:800px){.layout{display:block}aside{display:flex;gap:4px;overflow:auto;padding:10px}.nav{white-space:nowrap}.main{padding:28px 18px}.heading{display:block}.button{margin-top:18px}.stats,.grid{grid-template-columns:1fr}.top{padding:0 18px}}
</style></head><body><header class="top"><div class="brand"><span class="mark" aria-hidden="true">✦</span><span>eRPH Pro</span></div><div class="user">{{ auth()->user()->name }} · {{ $school->name }}</div></header><div class="layout"><aside><a class="nav active" href="{{ route('workspace.dashboard') }}">Overview</a><a class="nav" href="#teacher-record">Teacher record</a><a class="nav" href="#lesson-plans">Lesson plans</a><a class="nav" href="#reports">Reports</a></aside><main class="main"><div class="heading"><div><span class="eyebrow">{{ $school->subdomain }} workspace</span><h1>Good to see you, {{ Str::of(auth()->user()->name)->before(' ') }}.</h1><p>Your teaching workspace, kept clear and ready for the day.</p></div><a class="button" href="#lesson-plans">Create lesson plan</a></div><section class="stats"><div class="stat"><span>My lesson plans</span><strong>{{ $lessonPlanCount }}</strong></div><div class="stat"><span>Drafts to complete</span><strong>{{ $draftCount }}</strong></div><div class="stat"><span>Profile status</span><strong>{{ $profile ? 'Ready' : 'Set up' }}</strong></div></section><div class="grid"><section class="panel" id="teacher-record"><span class="eyebrow">Teacher record</span><h2>One profile, ready for every module.</h2><p>Your school record is the foundation for lesson plans, timetable, reports and future education modules. Official records remain owned by the school and can be exported when you move.</p><div class="profile"><div class="avatar">{{ Str::substr(auth()->user()->name, 0, 1) }}</div><div><strong>{{ auth()->user()->name }}</strong><span>{{ $profile?->position ?? 'Teacher profile pending' }}</span></div></div></section><section class="panel" id="lesson-plans"><span class="eyebrow">RPH workflow</span><h2>Lesson plans</h2><p>Keep the familiar school format while storing each revision safely for review and approval.</p><a class="button" href="#">Open my RPH</a></section></div></main></div></body></html>
